199	      const temp2 = (s0 + maj) >>> 0;
200	
201	      h = g;
202	      g = f;
203	      f = e;
204	      e = (d + temp1) >>> 0;
205	      d = c;
206	      c = b;
207	      b = a;
208	      a = (temp1 + temp2) >>> 0;
209	    }
210	
211	    h0 = (h0 + a) >>> 0;
212	    h1 = (h1 + b) >>> 0;
213	    h2 = (h2 + c) >>> 0;
214	    h3 = (h3 + d) >>> 0;
215	    h4 = (h4 + e) >>> 0;
216	    h5 = (h5 + f) >>> 0;
217	    h6 = (h6 + g) >>> 0;
