232	function serializeJson(value: unknown, pretty: boolean, sortKeys: boolean, level = 0, key?: string): string | undefined {
233	  if (value === undefined) return undefined;
234	  if (value === null || typeof value === "boolean" || typeof value === "string") return JSON.stringify(value);
235	  if (typeof value === "number") {
236	    if (!Number.isFinite(value)) throw new TypeError("canonical JSON does not support non-finite numbers");
237	    return FLOAT_FIELDS.has(key ?? "") && Number.isInteger(value) ? `${value}.0` : JSON.stringify(value);
238	  }
239	  if (Array.isArray(value)) {
240	    const items = value.map((item) => serializeJson(item, pretty, sortKeys, level + 1));
241	    return pretty && items.length > 0
242	      ? `[\n${items.map((item) => `${"  ".repeat(level + 1)}${item ?? "null"}`).join(",\n")}\n${"  ".repeat(level)}]`
