244	  }
245	  if (typeof value === "object") {
246	    const record = value as Record<string, unknown>;
247	    const keys = Object.keys(record);
248	    if (sortKeys) keys.sort();
249	    const entries = keys.flatMap((entryKey) => {
250	      const serialized = serializeJson(record[entryKey], pretty, sortKeys, level + 1, entryKey);
