252	    });
253	    return pretty && entries.length > 0
254	      ? `{\n${entries.map(([entryKey, serialized]) => `${"  ".repeat(level + 1)}${JSON.stringify(entryKey)}: ${serialized}`).join(",\n")}\n${"  ".repeat(level)}}`
