1	import { describe, expect, it } from "bun:test";
2	import { readFileSync } from "node:fs";
3	import { join } from "node:path";
4	import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
5	import {
6	  buildArenaTimeline,
7	  renderTimelineHtml,
8	} from "../src/games/restaurant-arena/timeline.js";
9	import {
10	  captureArenaTrace,
11	  exportTraceJson,
12	  exportTraceJsonl,
13	  validateArenaTraceV3,
14	} from "../src/games/restaurant-arena/trace.js";
15	import { milestoneFeedText } from "./restaurant-arena-milestones.js";
16	
17	describe("Restaurant Arena Overlay Timeline & Export (Issue #263)", () => {
18	  it("renders chronological cards for all 6 steps in the debrief / end-screen", () => {
19	    const game = new RestaurantGame(218220);
20	    game.step("sim_start");
21	    for (let i = 0; i < 8; i++) game.step("tick");
22	    game.step("verify_substitution");
23	    for (let i = 0; i < 16; i++) game.step("tick");
24	
25	    expect(game.isOver()).toBe(true);
26	
27	    const timeline = buildArenaTimeline(game);
28	    const html = renderTimelineHtml(timeline);
29	
30	    expect(timeline.milestonesPresented).toEqual(["original_decision", "correction", "later_probe", "outcome"]);
31	    expect(timeline.cards.map((card) => card.tick)).toEqual(game.getRecordedEvents().map((event) => event.tick));
32	    expect(html).toContain("protect safety and verify before substituting");
33	    expect(html).not.toContain("Correction stayed scoped");
34	    expect(html).toContain("This alone does not establish a worker response");
35	    expect(html).toContain("Shift Outcome Metrics");
36	  });
37	
38	  it("keeps the live Event Feed milestone spine in the required order", () => {
39	    expect(milestoneFeedText()).toBe(
40	      "ORIGINAL DECISION  →  PLAYER CORRECTION  →  LATER PROBE  →  SHIFT OUTCOMES",
41	    );
42	  });
43	
44	  it("produces valid restaurant-arena-trace-v3 JSON payload matching schema on export", () => {
45	    const game = new RestaurantGame(218220);
46	    game.step("sim_start");
47	    for (let i = 0; i < 24; i++) game.step("tick");
48	
49	    const trace = captureArenaTrace(game, { runKind: "live" });
50	    const json = exportTraceJson(trace);
51	    const parsed = JSON.parse(json);
52	
53	    // Validate using the schema validator
54	    const validation = validateArenaTraceV3(parsed);
55	    expect(validation.valid).toBe(true);
56	    expect(validation.errors).toEqual([]);
57	
58	    // Check against raw schema definition
59	    const schemaPath = join(import.meta.dir, "../contracts/restaurant-arena-trace-v3.schema.json");
