async function replayLastRun(): Promise<void> {
  const replay = lastReplay;
  if (!replay?.entry.create) return;
  if (replay.arenaTrace) replayArenaTrace(replay.arenaTrace); // Verify before animating the saved inputs.
  closePrompt();
  stopWorkerOrchestrator();
