  entry = replay.entry;
  variationCursor = replay.entry.variations.findIndex(({ id }) => id === replay.variationId);
  game = replay.entry.create(replay.variationId);
  game.reset(replay.seed);
  savedGame = undefined;
  activeTrace = undefined;
  sessionReceiptId = undefined;

function endGame(
  outcome: "completed" | "abandoned",
  reason: EpisodeEndReason = game?.hasWon() ? "won" : "game_over",
): void {
  if (!game || !entry || gameEnded) return;
  gameEnded = true;
  if (outcome === "abandoned" && game.name === "restaurant-arena") (game as unknown as RestaurantGame).markAbandoned(reason);
  const endedAtMs = Date.now();
  const variationId = entry.variations[variationCursor]?.id ?? "classic";
  const localScore = localScoreForCompletion({
    outcome,
    gameId: sessionReceiptId ?? `game_${gameSessionId ?? crypto.randomUUID()}`,
    gameType: entry.id,
    variationId,
    score: game.score(),
    success: game.hasWon(),
    endedAtMs,
    startedAtMs: gameStartedAt,
    platform: "overlay",
  });
  if (localScore) void invoke("append_local_score", { score: localScore }).then(refreshLocalScores).catch(() => undefined);
  if (outcome === "completed") {
    if (savedGame) {
      lastReplay = { entry, variationId, seed: savedGame.seed, actions: [...savedGame.actions],
        ...(game.name === "restaurant-arena" ? { arenaTrace: captureArenaTrace(game as unknown as RestaurantGame, { runKind: "live" }) } : {}) };
    }
    clearSavedGame();
    savedGame = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variationId,
    outcome,
    score: game.score(),
    success: outcome === "completed" && game.hasWon(),
    duration_ms: Math.max(0, endedAtMs - gameStartedAt),
    actions_taken: actionsTaken,
  }, gameSessionId);
  if (activeTrace) {
    const trace = activeTrace;
    const timeline = buildArenaTimeline(game as unknown as RestaurantGame);
    return renderTimelineHtml(timeline);
  } catch (err) {
    console.error("Failed to build arena timeline:", err);
    return "";
  }
}

/** Export the raw restaurant-arena-trace-v3 JSON or JSONL file. */
function exportCurrentTrace(format: "json" | "jsonl" = "json"): void {
  if (!game || game.name !== "restaurant-arena") return;
  try {
    // A shift played in the overlay is live gameplay by definition; synthetic
    // and benchmark traces are produced by scripts/export-arena-trace.ts.
    const trace = captureArenaTrace(game as unknown as RestaurantGame, {
      runKind: "live",
      ...(sessionReceiptId ? { sessionId: sessionReceiptId } : {}),
    });
    const content = format === "jsonl" ? exportTraceJsonl(trace) : exportTraceJson(trace);
    // Named by session, not episode: `episodeId` is the scenario, so every
    // run of the same seed used to download over the last one (#281).
    const filename = `restaurant-arena-trace-${trace.sessionId ?? trace.episodeId}.${format === "jsonl" ? "jsonl" : "json"}`;
    const mimeType = format === "jsonl" ? "application/x-ndjson" : "application/json";
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);

    const btn = screenElement.querySelector<HTMLButtonElement>('[data-action="export-trace"]');
    if (btn) {
      const orig = btn.innerHTML;
      btn.innerHTML = "Exported!";
      setTimeout(() => {
        if (btn) btn.innerHTML = orig;
      }, 2000);
    }

