  actionsTaken = 0;
  gameEnded = true;
  replaying = true;
  screen = "game";
  renderGameScreen();
  const replayGame = game;
  const inputs = replay.arenaTrace?.replay.inputs ?? replay.actions;
  for (const [index, action] of inputs.entries()) {
    await new Promise((resolve) => setTimeout(resolve, 650));
    if (game !== replayGame || screen !== "game") {
      replaying = false;
      return;
    }
    if (typeof action === "string") replayGame.step(action);
    else applyArenaReplayInput(replayGame as unknown as RestaurantGame, action, index);
    actionsTaken++;
    drawGame();
  }
  replaying = false;
  if (game === replayGame) openPrompt("game-over");
}

function exitToMenu(): void {
  stopWorkerOrchestrator();
  endGame("abandoned", "user_quit");
  stopGravity();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  screen = "menu";
  closePrompt();
  delete screenElement.dataset.game;
  drawMenu();
}

