arguments.command:
bun -e "
const d=JSON.parse(require('fs').readFileSync('docs/evidence/issue-275/played-shift.json','utf8'));
console.log(Object.keys(d));
for(const k of Object.keys(d)) if(!['events','initialState','replay'].includes(k)) console.log(k, JSON.stringify(d[k]));
console.log('events',d.events.length,'inputs',d.replay.inputs.length, d.replay.variation, d.replay.finalStateHash, d.replay.finalRestaurantStateHash);
console.log('workers', JSON.stringify(d.initialState.workers));
console.log('roles in events', [...new Set(d.events.map(e=>e.role))]);
d.replay.inputs.forEach((i,n)=>console.log(n, i.kind, i.tick, i.action ?? JSON.stringify(i.roles ?? i.envelope?.action ?? '')));
"

