// ── Capture ──────────────────────────────────────────────────────────────

export interface TraceCaptureOptions {
  episodeId?: string;
  sessionId?: string;
  /** Required: live gameplay, synthetic episodes and benchmark episodes must stay distinguishable. */
  runKind: "live" | "synthetic" | "benchmark";
  envVersion?: string;
  /**
   * Re-bases every captured event timestamp onto this instant, one
   * `MS_PER_TICK` step per tick. Scripted exports pass it so the same played
   * shift produces the same bytes; live capture omits it and keeps the
   * timestamps the run actually recorded.
   */
  startTime?: string;
  deletion?: Partial<TraceV3Deletion>;
  /** Omit to capture the run's own recorded event journal; pass to replace it wholesale. */
  events?: TraceV3Event[];
  /**
   * Events the caller wants merged into the captured journal alongside the
   * game's own recorded events (e.g. an out-of-band player note). Each one is
   * stamped with the round its `tick` falls in, so a caller cannot introduce
   * an event the reviewer cannot line up against the round it belongs to.
   */
  additionalEvents?: TraceV3Event[];
}

const RUN_KINDS: readonly TraceCaptureOptions["runKind"][] = ["live", "synthetic", "benchmark"];

function episodeIdFor(initialState: Record<string, unknown>, variation: string, seed: number): string {
  const episode = initialState.episode as { id?: unknown } | undefined;
  return typeof episode?.id === "string" && episode.id ? episode.id : `${variation}-${seed}`;
}

/**
 * Capture a complete, replayable `restaurant-arena-trace/v3` record from a
 * running game: its tick-0 state, its event journal, and the ordered inputs
 * plus checkpoint hashes `replayArenaTrace` re-derives.
 *
 * `RestaurantGame.captureTrace` is a thin wrapper around this, so a caller that
 * holds a game and one that only holds a module import get the same record.
 */
export function captureArenaTrace(game: RestaurantGame, options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  if (typeof options !== "object" || options === null) {
    throw new TypeError("captureArenaTrace requires an options object naming a runKind");
  }
  if (!RUN_KINDS.includes(options.runKind)) {
    throw new TypeError(
      `captureArenaTrace requires runKind of ${RUN_KINDS.map((kind) => `"${kind}"`).join(", ")}; received ${JSON.stringify(options.runKind)}`,
    );
  }

  const initialState = game.getInitialState();
  const replay = game.getReplayRecord();
  const seed = typeof initialState.seed === "number" ? initialState.seed : game.state().seed;
  const ticksPerRound = game.contract().ticksPerRound;

  const journal = rebaseTimestamps(options.events ?? game.getRecordedEvents(), options.startTime);
  const additional = (options.additionalEvents ?? []).map((event) => ({
    ...event,
    round: roundForTick(event.tick, ticksPerRound),
  }));

  return {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? episodeIdFor(initialState, replay.variation, seed),
    ...(options.sessionId !== undefined ? { sessionId: options.sessionId } : {}),
    seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState,
    events: mergeEventsByTick(journal, additional),
    replay,
    terminal: game.getTerminalStatus(),
    deletion: {
      requestId: options.deletion?.requestId ?? null,
      status: options.deletion?.status ?? "retained",
    },
  };
}

function rebaseTimestamps(events: readonly TraceV3Event[], startTime?: string): TraceV3Event[] {
  if (startTime === undefined) return events.map((event) => ({ ...event }));
  const base = Date.parse(startTime);
  if (!Number.isFinite(base)) throw new TypeError(`captureArenaTrace startTime is not a date: ${JSON.stringify(startTime)}`);
  return events.map((event) => ({
    ...event,
    timestamp: new Date(base + event.tick * MS_PER_TICK).toISOString(),
  }));
}

/**
 * Caller-supplied events land in tick order among the game's own, so the
 * journal a reviewer reads is still chronological. Stable within a tick: the
 * run's own events come first.
 */
function mergeEventsByTick(journal: TraceV3Event[], additional: TraceV3Event[]): TraceV3Event[] {
  if (additional.length === 0) return journal;
  return [
    ...journal.map((event) => ({ event, source: 0 })),
    ...additional.map((event) => ({ event, source: 1 })),
  ]
    .sort((a, b) => a.event.tick - b.event.tick || a.source - b.source)
    .map(({ event }) => event);
}

// ── Export ───────────────────────────────────────────────────────────────

/** The whole record as one pretty-printed JSON document. */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${JSON.stringify(trace, null, 2)}\n`;
}

/**
 * Newline-delimited streaming form: a header line carrying everything but the
 * journal, then one line per event. Re-assembling is `{ ...header, events }`.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return `${[JSON.stringify(header), ...events.map((event) => JSON.stringify(event))].join("\n")}\n`;
}

// ── Validation ───────────────────────────────────────────────────────────

export interface TraceValidationResult {
  valid: boolean;
  errors: string[];
}

const ARENA_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,129}$/;
const STATE_HASH = /^sha256:[0-9a-f]{64}$/;
const TIMESTAMP = /^\d{4}-\d{2}-\d{2}[Tt]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$/;

const TRACE_EVENT_KINDS: readonly string[] = [
  "observation", "action", "player_correction", "message", "outcome", "inspection", "hold",
  "hold_cleared", "verification_request", "verification_response", "escalation", "handoff",
  "supply_order", "supply_delivered", "stockout",
];
/** Includes the legacy `expediter`: historical traces named it and stay valid. */
const TRACE_ROLES: readonly string[] = ["host", "supply_lead", "chef", "server", "expediter"];
const VARIATIONS: readonly string[] = ["tutorial-shift", "dinner-rush", "quiet-tuesday", "saturday-night"];
const CORRECTION_CATEGORIES: readonly string[] = ["safety", "priority", "quality", "pace"];
const SUBJECT_KINDS: readonly string[] = ["order", "ingredient", "equipment", "handoff"];
const DELETION_STATUSES: readonly string[] = ["retained", "requested", "deleted"];
const TERMINAL_STATUSES: readonly string[] = ["active", "completed", "abandoned"];

const TRACE_KEYS: readonly string[] = [
  "version", "episodeId", "sessionId", "seed", "envVersion", "contractVersion", "runKind",
  "initialState", "events", "deletion", "replay", "terminal",
];
const EVENT_KEYS: readonly string[] = [
  "tick", "round", "kind", "timestamp", "stateHash", "actorId", "role", "targetRole", "checkpointId",
  "model", "requestId", "idempotencyKey", "text", "observation", "action", "toolResult", "outcome",
  "correctionRationale", "correctionCategory", "changedDecisionEventId", "probeEventId", "subject",
  "payload",
];
const INPUT_KEYS: Record<string, readonly string[]> = {
  step: ["kind", "tick", "stateHash", "restaurantStateHash", "action"],
  time: ["kind", "tick", "stateHash", "restaurantStateHash"],
  envelope: ["kind", "tick", "stateHash", "restaurantStateHash", "envelope", "telemetry"],
  controllers: ["kind", "tick", "stateHash", "restaurantStateHash", "roles"],
};
const INPUT_REQUIRED: Record<string, readonly string[]> = {
  step: ["kind", "tick", "stateHash", "action"],
  time: ["kind", "tick", "stateHash"],
  envelope: ["kind", "tick", "stateHash", "envelope"],
  controllers: ["kind", "tick", "stateHash", "roles"],
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

class FieldErrors {
  readonly errors: string[] = [];

  add(path: string, message: string): void {
    this.errors.push(`${path}: ${message}`);
  }

  /** True when the field is present and well-formed, so callers can stop drilling. */
  check(path: string, value: unknown, message: string, ok: (value: unknown) => boolean): boolean {
    if (ok(value)) return true;
    this.add(path, message);
    return false;
  }

  required(path: string, container: Record<string, unknown>, keys: readonly string[]): void {
    for (const key of keys) {
      if (container[key] === undefined) this.add(`${path}${path ? "." : ""}${key}`, "is required");
    }
  }

  noExtraKeys(path: string, container: Record<string, unknown>, allowed: readonly string[]): void {
    for (const key of Object.keys(container)) {
      if (!allowed.includes(key)) this.add(`${path}${path ? "." : ""}${key}`, "is not a known field");
    }
  }
}

const isArenaId = (value: unknown): boolean => typeof value === "string" && ARENA_ID.test(value);
const isStateHash = (value: unknown): boolean => typeof value === "string" && STATE_HASH.test(value);
const isTick = (value: unknown): boolean => typeof value === "number" && Number.isInteger(value) && value >= 0;
const isNullableString = (value: unknown): boolean => value === null || typeof value === "string";
const isNullableRecord = (value: unknown): boolean => value === null || isRecord(value);
const isNullableArenaId = (value: unknown): boolean => value === null || isArenaId(value);

/**
 * Field-by-field check of a decoded record against
 * `contracts/restaurant-arena-trace-v3.schema.json`. Reports every problem it
 * finds rather than the first, so a malformed export can be fixed in one pass.
 */
export function validateArenaTraceV3(value: unknown): TraceValidationResult {
  const found = new FieldErrors();
  if (!isRecord(value)) {
    found.add("", "trace must be a JSON object");
    return { valid: false, errors: found.errors };
  }
  const trace = value;

  found.required("", trace, [
    "version", "episodeId", "seed", "envVersion", "contractVersion", "runKind", "initialState",
    "events", "deletion", "replay", "terminal",
  ]);
  found.noExtraKeys("", trace, TRACE_KEYS);

  if (trace.version !== undefined) {
    found.check("version", trace.version, `must be "${TRACE_V3_VERSION}"`, (v) => v === TRACE_V3_VERSION);
  }
  if (trace.episodeId !== undefined) {
    found.check("episodeId", trace.episodeId, `must match ${ARENA_ID.source}`, isArenaId);
  }
  if (trace.sessionId !== undefined) {
    found.check("sessionId", trace.sessionId, `must match ${ARENA_ID.source}`, isArenaId);
  }
  if (trace.seed !== undefined) {
    found.check("seed", trace.seed, "must be an integer >= 0", isTick);
  }
  if (trace.envVersion !== undefined) {
    found.check("envVersion", trace.envVersion, "must be a non-empty string", (v) => typeof v === "string" && v.length > 0);
  }
  if (trace.contractVersion !== undefined) {
    found.check("contractVersion", trace.contractVersion, `must be "${TRACE_V3_CONTRACT_VERSION}"`, (v) => v === TRACE_V3_CONTRACT_VERSION);
  }
  if (trace.runKind !== undefined) {
    found.check("runKind", trace.runKind, `must be one of ${RUN_KINDS.join(", ")}`, (v) => RUN_KINDS.includes(v as never));
  }

  if (trace.initialState !== undefined) validateInitialState(found, trace.initialState);
  if (trace.events !== undefined) {
    if (found.check("events", trace.events, "must be an array", Array.isArray)) {
      (trace.events as unknown[]).forEach((event, index) => validateEvent(found, `events[${index}]`, event));
    }
  }
  if (trace.deletion !== undefined) validateDeletion(found, trace.deletion);
  if (trace.replay !== undefined) validateReplay(found, trace.replay);
  if (trace.terminal !== undefined) validateTerminal(found, trace.terminal);

  return { valid: found.errors.length === 0, errors: found.errors };
}

function validateInitialState(found: FieldErrors, value: unknown): void {
  if (!found.check("initialState", value, "must be a JSON object", isRecord)) return;
  const state = value as Record<string, unknown>;
  found.required("initialState", state, [
    "version", "seed", "episode", "clock", "tables", "orders", "inventory", "equipment", "workers",
    "reputation", "outcomes",
  ]);
  found.check("initialState.version", state.version, `must be "${TRACE_V3_CONTRACT_VERSION}"`, (v) => v === TRACE_V3_CONTRACT_VERSION);
  found.check("initialState.seed", state.seed, "must be an integer >= 0", isTick);
  found.check("initialState.reputation", state.reputation, "must be a number in 0..100", (v) => typeof v === "number" && v >= 0 && v <= 100);
  for (const key of ["tables", "orders", "equipment", "workers"]) {
    if (state[key] !== undefined) found.check(`initialState.${key}`, state[key], "must be an array", Array.isArray);
  }
  if (isRecord(state.episode)) {
    found.required("initialState.episode", state.episode, ["id", "phase", "tick", "maxTicks"]);
    found.check("initialState.episode.id", state.episode.id, `must match ${ARENA_ID.source}`, isArenaId);
    found.check("initialState.episode.phase", state.episode.phase, 'must be "active" or "complete"', (v) => v === "active" || v === "complete");
    found.check("initialState.episode.tick", state.episode.tick, "must be an integer >= 0", isTick);
    found.check("initialState.episode.maxTicks", state.episode.maxTicks, "must be an integer >= 1", (v) => isTick(v) && (v as number) >= 1);
  } else if (state.episode !== undefined) {
    found.add("initialState.episode", "must be a JSON object");
  }
  (state.workers as unknown[] | undefined)?.forEach((worker, index) => {
    const path = `initialState.workers[${index}]`;
    if (!isRecord(worker)) return void found.add(path, "must be a JSON object");
    found.check(`${path}.id`, worker.id, `must match ${ARENA_ID.source}`, isArenaId);
    found.check(`${path}.role`, worker.role, `must be one of ${TRACE_ROLES.join(", ")}`, (v) => TRACE_ROLES.includes(v as string));
    found.check(`${path}.load`, worker.load, "must be a number in 0..1", (v) => typeof v === "number" && v >= 0 && v <= 1);
  });
  // The remaining fields are the shared v1 state contract; one gate covers them
  // rather than restating a second copy of it here.
  if (found.errors.every((error) => !error.startsWith("initialState")) && !isRestaurantState(state)) {
    found.add("initialState", "does not satisfy the restaurant-arena/v1 state contract");
  }
}

function validateEvent(found: FieldErrors, path: string, value: unknown): void {
  if (!found.check(path, value, "must be a JSON object", isRecord)) return;
  const event = value as Record<string, unknown>;
  found.required(path, event, ["tick", "kind", "timestamp", "stateHash"]);
  found.noExtraKeys(path, event, EVENT_KEYS);

  const optional: Array<[string, (v: unknown) => boolean, string]> = [
    ["tick", isTick, "must be an integer >= 0"],
    ["round", (v) => isTick(v) && (v as number) >= 1, "must be an integer >= 1"],
    ["kind", (v) => TRACE_EVENT_KINDS.includes(v as string), `must be one of ${TRACE_EVENT_KINDS.join(", ")}`],
    ["timestamp", (v) => typeof v === "string" && TIMESTAMP.test(v), "must be an RFC 3339 date-time"],
    ["stateHash", isStateHash, `must match ${STATE_HASH.source}`],
    ["actorId", isArenaId, `must match ${ARENA_ID.source}`],
    ["role", (v) => TRACE_ROLES.includes(v as string), `must be one of ${TRACE_ROLES.join(", ")}`],
    ["targetRole", (v) => TRACE_ROLES.includes(v as string), `must be one of ${TRACE_ROLES.join(", ")}`],
    ["checkpointId", isArenaId, `must match ${ARENA_ID.source}`],
    ["requestId", isArenaId, `must match ${ARENA_ID.source}`],
    ["idempotencyKey", (v) => typeof v === "string" && IDEMPOTENCY_KEY.test(v), `must match ${IDEMPOTENCY_KEY.source}`],
    ["text", isNullableString, "must be a string or null"],
    ["observation", isNullableRecord, "must be an object or null"],
    ["action", isNullableRecord, "must be an object or null"],
    ["outcome", isNullableRecord, "must be an object or null"],
    ["payload", isNullableRecord, "must be an object or null"],
    ["correctionRationale", isNullableString, "must be a string or null"],
    ["correctionCategory", (v) => v === null || CORRECTION_CATEGORIES.includes(v as string), `must be null or one of ${CORRECTION_CATEGORIES.join(", ")}`],
    ["changedDecisionEventId", isNullableArenaId, `must be null or match ${ARENA_ID.source}`],
    ["probeEventId", isNullableArenaId, `must be null or match ${ARENA_ID.source}`],
  ];
  for (const [key, ok, message] of optional) {
    if (event[key] !== undefined) found.check(`${path}.${key}`, event[key], message, ok);
  }

  if (event.model !== undefined) {
    if (found.check(`${path}.model`, event.model, "must be a JSON object", isRecord)) {
      const model = event.model as Record<string, unknown>;
      found.required(`${path}.model`, model, ["provider", "name"]);
      found.noExtraKeys(`${path}.model`, model, ["provider", "name", "version"]);
      for (const key of ["provider", "name", "version"]) {
        if (model[key] !== undefined) {
          found.check(`${path}.model.${key}`, model[key], "must be a non-empty string", (v) => typeof v === "string" && v.length > 0);
        }
      }
    }
  }
  if (event.subject !== undefined) {
    if (found.check(`${path}.subject`, event.subject, "must be a JSON object", isRecord)) {
      const subject = event.subject as Record<string, unknown>;
      found.required(`${path}.subject`, subject, ["kind", "id"]);
      found.noExtraKeys(`${path}.subject`, subject, ["kind", "id"]);
      if (subject.kind !== undefined) {
        found.check(`${path}.subject.kind`, subject.kind, `must be one of ${SUBJECT_KINDS.join(", ")}`, (v) => SUBJECT_KINDS.includes(v as string));
      }
      if (subject.id !== undefined) found.check(`${path}.subject.id`, subject.id, `must match ${ARENA_ID.source}`, isArenaId);
    }
  }
  if (event.toolResult !== undefined && event.toolResult !== null) {
    validateToolResult(found, `${path}.toolResult`, event.toolResult);
  }
}

function validateToolResult(found: FieldErrors, path: string, value: unknown): void {
  if (!found.check(path, value, "must be an object or null", isRecord)) return;
  const result = value as Record<string, unknown>;
  if (result.ok !== undefined) found.check(`${path}.ok`, result.ok, "must be a boolean", (v) => typeof v === "boolean");
  if (result.latencyMs !== undefined) {
    found.check(`${path}.latencyMs`, result.latencyMs, "must be a number >= 0", (v) => typeof v === "number" && v >= 0);
  }
  const error = result.error;
  if (error !== undefined && error !== null) {
    if (found.check(`${path}.error`, error, "must be an object or null", isRecord)) {
      const body = error as Record<string, unknown>;
      found.required(`${path}.error`, body, ["code", "message"]);
      for (const key of ["code", "message"]) {
        if (body[key] !== undefined) {
          found.check(`${path}.error.${key}`, body[key], "must be a non-empty string", (v) => typeof v === "string" && v.length > 0);
        }
      }
      if (body.retryable !== undefined) {
        found.check(`${path}.error.retryable`, body.retryable, "must be a boolean", (v) => typeof v === "boolean");
      }
    }
    // A grader filtering on `ok` and one filtering on error presence must agree.
    if (result.ok !== false) found.add(`${path}.ok`, "must be false when an error body is present");
  } else if (result.ok === false) {
    found.add(`${path}.error`, "is required when ok is false");
  }
}

function validateDeletion(found: FieldErrors, value: unknown): void {
  if (!found.check("deletion", value, "must be a JSON object", isRecord)) return;
  const deletion = value as Record<string, unknown>;
  found.required("deletion", deletion, ["requestId", "status"]);
  found.noExtraKeys("deletion", deletion, ["requestId", "status"]);
  if (deletion.requestId !== undefined) {
    found.check("deletion.requestId", deletion.requestId, `must be null or match ${ARENA_ID.source}`, isNullableArenaId);
  }
  if (deletion.status !== undefined) {
    found.check("deletion.status", deletion.status, `must be one of ${DELETION_STATUSES.join(", ")}`, (v) => DELETION_STATUSES.includes(v as string));
  }
}

function validateTerminal(found: FieldErrors, value: unknown): void {
  if (!found.check("terminal", value, "must be a JSON object", isRecord)) return;
  const terminal = value as Record<string, unknown>;
  found.required("terminal", terminal, ["status", "tick", "reason"]);
  found.noExtraKeys("terminal", terminal, ["status", "tick", "reason"]);
  if (terminal.status !== undefined) {
    found.check("terminal.status", terminal.status, `must be one of ${TERMINAL_STATUSES.join(", ")}`, (v) => TERMINAL_STATUSES.includes(v as string));
  }
  if (terminal.tick !== undefined) found.check("terminal.tick", terminal.tick, "must be an integer >= 0", isTick);
  if (terminal.reason !== undefined) found.check("terminal.reason", terminal.reason, "must be a string or null", isNullableString);
}

function validateReplay(found: FieldErrors, value: unknown): void {
  if (!found.check("replay", value, "must be a JSON object", isRecord)) return;
  const replay = value as Record<string, unknown>;
  found.required("replay", replay, ["variation", "inputs", "finalStateHash"]);
  found.noExtraKeys("replay", replay, ["variation", "inputs", "finalStateHash", "finalRestaurantStateHash"]);
  if (replay.variation !== undefined) {
    found.check("replay.variation", replay.variation, `must be one of ${VARIATIONS.join(", ")}`, (v) => VARIATIONS.includes(v as string));
  }
  if (replay.finalStateHash !== undefined) {
    found.check("replay.finalStateHash", replay.finalStateHash, `must match ${STATE_HASH.source}`, isStateHash);
  }
  if (replay.finalRestaurantStateHash !== undefined) {
    found.check("replay.finalRestaurantStateHash", replay.finalRestaurantStateHash, `must match ${STATE_HASH.source}`, isStateHash);
  }
  if (replay.inputs === undefined) return;
  if (!found.check("replay.inputs", replay.inputs, "must be an array", Array.isArray)) return;
  (replay.inputs as unknown[]).forEach((input, index) => validateInput(found, `replay.inputs[${index}]`, input));
}

function validateInput(found: FieldErrors, path: string, value: unknown): void {
  if (!found.check(path, value, "must be a JSON object", isRecord)) return;
  const input = value as Record<string, unknown>;
  const kind = input.kind;
  if (typeof kind !== "string" || !(kind in INPUT_KEYS)) {
    found.add(`${path}.kind`, `must be one of ${Object.keys(INPUT_KEYS).join(", ")}`);
    return;
  }
  found.required(path, input, INPUT_REQUIRED[kind]!);
  found.noExtraKeys(path, input, INPUT_KEYS[kind]!);
  if (input.tick !== undefined) found.check(`${path}.tick`, input.tick, "must be an integer >= 0", isTick);
  if (input.stateHash !== undefined) found.check(`${path}.stateHash`, input.stateHash, `must match ${STATE_HASH.source}`, isStateHash);
  if (input.restaurantStateHash !== undefined) {
    found.check(`${path}.restaurantStateHash`, input.restaurantStateHash, `must match ${STATE_HASH.source}`, isStateHash);
  }
  if (kind === "step" && input.action !== undefined) {
    found.check(`${path}.action`, input.action, "must be a non-empty string", (v) => typeof v === "string" && v.length > 0);
  }
  if (kind === "envelope") {
    if (input.envelope !== undefined) {
      found.check(`${path}.envelope`, input.envelope, "must be a restaurant-arena-action/v1 envelope", isActionEnvelope);
    }
    if (input.telemetry !== undefined) {
      found.check(`${path}.telemetry`, input.telemetry, "must be a JSON object", isRecord);
    }
  }
  if (kind === "controllers" && input.roles !== undefined) {
    if (found.check(`${path}.roles`, input.roles, "must be an array", Array.isArray)) {
      const roles = input.roles as unknown[];
      roles.forEach((role, index) => {
        found.check(`${path}.roles[${index}]`, role, `must be one of ${TRACE_ROLES.join(", ")}`, (v) => TRACE_ROLES.includes(v as string));
      });
      if (new Set(roles).size !== roles.length) found.add(`${path}.roles`, "must not repeat a role");
    }
  }
}

