/**
 * Native replay of a captured `restaurant-arena-trace/v3` record.
 *
 * Replay is the check that a trace is *true*, not merely well-formed: the
 * record is rebuilt by re-running this engine from the seed and comparing every
 * checkpoint the recording claimed. See
 * docs/restaurant-arena-trace-contract.md.
 */

import { RestaurantGame, type ArenaInputRecord, type RestaurantGameAction } from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";
import type { Role } from "./types.js";

/** The legacy roster this engine renamed. Only the name is legacy, not the behavior. */
const LEGACY_ROLE = "expediter";
const LEGACY_WORKER_ID = "worker-expediter";
const CANONICAL_ROLE = "supply_lead";
const CANONICAL_WORKER_ID = "worker-supply_lead";

/**
 * The tick-0 state as both sides can agree to spell it.
 *
 * Historical traces name the `expediter` worker where this engine now names
 * `supply_lead`, and listed the roster in a different order. Both are the same
 * worker doing the same job, so the role/id pair is mapped and the roster put
 * in a fixed order before hashing. Nothing else is touched: every other field —
 * `cash` included — has to match what the seed actually produces.
 */
function canonicalInitialState(state: Record<string, unknown>): Record<string, unknown> {
  const canonical = JSON.parse(JSON.stringify(state)) as Record<string, unknown>;
  if (!Array.isArray(canonical.workers)) return canonical;
  canonical.workers = (canonical.workers as Array<Record<string, unknown>>)
    .map((worker) => ({
      ...worker,
      ...(worker.id === LEGACY_WORKER_ID ? { id: CANONICAL_WORKER_ID } : {}),
      ...(worker.role === LEGACY_ROLE ? { role: CANONICAL_ROLE } : {}),
    }))
    .sort((a, b) => sortKey(a).localeCompare(sortKey(b)));
  return canonical;
}

function sortKey(worker: Record<string, unknown>): string {
  return `${String(worker.role ?? "")}�${String(worker.id ?? "")}`;
}

/**
 * Apply one recorded input to a live game and verify the checkpoint it lands
 * on. Throws on the first hash that disagrees, naming the input's position so
 * the divergence can be found in the record.
 */
export function applyArenaReplayInput(game: RestaurantGame, input: ArenaInputRecord, index: number): void {
  switch (input.kind) {
    case "step":
      game.step(input.action as RestaurantGameAction);
      break;
    case "time":
      game.advanceTime();
      break;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      break;
    case "controllers":
      game.setExternalControllers(input.roles as Role[]);
      break;
    default:
      throw new Error(`replay input ${index} has unknown kind ${JSON.stringify((input as { kind: unknown }).kind)}`);
  }

  const stateHash = computeStateHash(game.checkpointState());
  if (stateHash !== input.stateHash) {
    throw new Error(
      `replay checkpoint mismatch at input ${index} (${input.kind}, tick ${input.tick}): recorded ${input.stateHash}, replayed ${stateHash}`,
    );
  }
  if (input.restaurantStateHash !== undefined) {
    const restaurantStateHash = computeStateHash(game.state());
    if (restaurantStateHash !== input.restaurantStateHash) {
      throw new Error(
        `replay state mismatch at input ${index} (${input.kind}, tick ${input.tick}): recorded ${input.restaurantStateHash}, replayed ${restaurantStateHash}`,
      );
    }
  }
}

/**
 * Rebuild the live game a trace records and hand it back.
 *
 * The returned value is the `RestaurantGame` itself, so a caller can go on to
 * ask it anything a live game answers — `.checkpointState()`, `.state()`,
 * `.getTerminalStatus()`.
 *
 * Replay starts from a freshly constructed game for the recorded seed and
 * variation, never from `trace.initialState` taken on faith: the recorded
 * tick-0 state is checked against what this engine's own seed produces before
 * a single input is applied. Then every checkpoint hash, the final state hash,
 * and the whole terminal record — status, tick and reason — must agree with
 * what replay actually reaches.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);

  const recordedInitialHash = computeStateHash(canonicalInitialState(trace.initialState));
  const replayedInitialHash = computeStateHash(canonicalInitialState(game.getInitialState()));
  if (recordedInitialHash !== replayedInitialHash) {
    throw new Error(
      `initial state mismatch for seed ${trace.seed} (${trace.replay.variation}): recorded ${recordedInitialHash}, replayed ${replayedInitialHash}`,
    );
  }

  trace.replay.inputs.forEach((input, index) => applyArenaReplayInput(game, input, index));

  const finalStateHash = computeStateHash(game.checkpointState());
  if (finalStateHash !== trace.replay.finalStateHash) {
    throw new Error(
      `replay final state mismatch: recorded ${trace.replay.finalStateHash}, replayed ${finalStateHash}`,
    );
  }
  if (trace.replay.finalRestaurantStateHash !== undefined) {
    const finalRestaurantStateHash = computeStateHash(game.state());
    if (finalRestaurantStateHash !== trace.replay.finalRestaurantStateHash) {
      throw new Error(
        `replay final restaurant state mismatch: recorded ${trace.replay.finalRestaurantStateHash}, replayed ${finalRestaurantStateHash}`,
      );
    }
  }

  // The whole terminal record, not just the status: a trace whose reason has
  // been rewritten is as untrue as one whose status has.
  const terminal = game.getTerminalStatus();
  const recorded = trace.terminal;
  if (
    terminal.status !== recorded?.status ||
    terminal.tick !== recorded.tick ||
    (terminal.reason ?? null) !== (recorded.reason ?? null)
  ) {
    throw new Error(
      `terminal mismatch: recorded ${JSON.stringify(recorded)}, replayed ${JSON.stringify(terminal)}`,
    );
  }

  return game;
}

