/**
 * The whole record as one pretty-printed JSON document, in the order the record
 * declares its fields and with the backend's decimal spelling for float fields
 * (`"cash": 107.0`) so a consumer that types `cash` as a float decodes one.
 */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${serializeJson(trace, true, false) ?? "null"}\n`;
}

/**
 * Newline-delimited streaming form: a header line carrying everything but the
 * journal, then one line per event. Re-assembling is `{ ...header, events }`.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  const lines = [header, ...events].map((line) => serializeJson(line, false, false) ?? "null");
  return `${lines.join("\n")}\n`;
}

