const want = readFileSync("contracts/fixtures/restaurant-arena-trace-v3.json", "utf8");
console.log("fixture identical:", got === want);
if (got !== want) { const g=got.split("\n"), w=want.split("\n"); for (let i=0;i<Math.max(g.length,w.length);i++) if (g[i]!==w[i]) { console.log("diff line",i+1,"\n got:",g[i],"\nwant:",w[i]); break; } }
const jsonl = exportTraceJsonl(trace);
console.log("jsonl lines", jsonl.trim().split("\n").length, "events", trace.events.length);
console.log("header has events?", "events" in JSON.parse(jsonl.split("\n")[0]));

// legacy expediter trace
for (const p of ["docs/evidence/issue-275/played-shift.json"]) {
