  console.log(p, "validate:", JSON.stringify(validateArenaTraceV3(t)).slice(0, 800));
  const g = replayArenaTrace(t);
  console.log(p, "replayed terminal", JSON.stringify(g.getTerminalStatus()));
}
' 2>&1 | head -40

