  return inputs.flatMap(jsonFiles).flatMap((path) => {
    try {
      const value = JSON.parse(readFileSync(path, "utf8")) as TraceEventChunk;
      return value.schema_version === 2 && Array.isArray(value.events) ? [value] : [];
    } catch (error) {
