import { exportTraceJson, validateArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

const FIXTURE = resolve(import.meta.dir, "..", "contracts", "fixtures", "restaurant-arena-trace-v3.json");

const BENCHMARK = {
  seed: 218220,
  variation: "dinner-rush",
  episodeId: "dinner-rush-benchmark-218220",
  /** Frozen so the fixture's timestamps do not move with the wall clock. */
  startTime: "2026-09-05T18:00:00.000Z",
  /** Ticks before the manager verifies the chef's substitution, then to the end of the shift. */
  ticksBeforeCorrection: 10,
  ticksAfterCorrection: 14,
} as const;

function captureBenchmarkTrace() {
  const game = new RestaurantGame(BENCHMARK.seed, BENCHMARK.variation);
  game.step("sim_start");
  for (let i = 0; i < BENCHMARK.ticksBeforeCorrection; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < BENCHMARK.ticksAfterCorrection; i++) game.step("tick");
  return game.captureTrace({
    runKind: "benchmark",
    episodeId: BENCHMARK.episodeId,
    startTime: BENCHMARK.startTime,
  });
}

