/**
 * Natively replay a captured trace file and report whether it is true.
 *
 *   bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>
 *
 * Both export shapes are accepted: the single JSON document from
 * `exportTraceJson` and the newline-delimited form from `exportTraceJsonl`.
 * A trace passes only if it is schema-valid *and* this engine, re-run from the
 * recorded seed, reaches every checkpoint and the exact terminal record the
 * file claims. See docs/restaurant-arena-trace-contract.md.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { validateArenaTraceV3, type RestaurantArenaTraceV3 } from "../src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

/** JSONL is a header line plus one line per event; JSON is the whole record. */
function parseTrace(path: string, text: string): unknown {
  const asJsonl = () => {
    const [header, ...events] = text.split("\n").filter((line) => line.trim().length > 0).map((line) => JSON.parse(line) as unknown);
    if (header === undefined) throw new Error("trace file is empty");
    return { ...(header as Record<string, unknown>), events };
  };
  if (path.endsWith(".jsonl")) return asJsonl();
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return asJsonl();
  }
}

const [pathArgument, ...rest] = process.argv.slice(2);
if (!pathArgument || rest.length > 0) usage();
const path = resolve(pathArgument);

let trace: unknown;
try {
  trace = parseTrace(path, readFileSync(path, "utf8"));
} catch (error) {
  console.error(`Could not read ${path}: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

const validation = validateArenaTraceV3(trace);
if (!validation.valid) {
  console.error(`Schema validation failed for ${path}:\n${validation.errors.map((error) => `  ${error}`).join("\n")}`);
  process.exit(1);
}

const record = trace as RestaurantArenaTraceV3;
let game;
try {
  game = replayArenaTrace(record);
} catch (error) {
  console.error(`Native replay failed for ${path}: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

const terminal = game.getTerminalStatus();
console.log(`${record.replay.inputs.length} inputs, tick ${terminal.tick}, ${terminal.status}`);
console.log(record.replay.finalStateHash);
console.log(`Native replay passed: ${path} (${record.events.length} events, runKind ${record.runKind})`);

