arguments.command:
bun -e '
import { RestaurantGame } from "./src/games/restaurant-arena/restaurant-game.js";
import { captureArenaTrace, exportTraceJson, exportTraceJsonl, validateArenaTraceV3 } from "./src/games/restaurant-arena/trace.js";
import { replayArenaTrace } from "./src/games/restaurant-arena/replay.js";

function play(seed = 218220) {
  const g = new RestaurantGame(seed, "dinner-rush");
  g.step("sim_start");
  for (let i = 0; i < 10; i++) g.step("tick");
  g.step("verify_substitution");
  for (let i = 0; i < 14; i++) g.step("tick");
  return g;
}
const clone = (t: unknown) => JSON.parse(JSON.stringify(t));
const base = captureArenaTrace(play(), { runKind: "benchmark" });
console.log("episodeId default:", base.episodeId);

// legacy roster
const legacy = clone(base);
legacy.initialState.workers = [
  { id: "worker-chef", role: "chef", load: 0, location: "kitchen" },
  { id: "worker-server", role: "server", load: 0, location: "floor" },
  { id: "worker-host", role: "host", load: 0, location: "queue" },
  { id: "worker-expediter", role: "expediter", load: 0, location: "pass" },
];
console.log("legacy valid:", validateArenaTraceV3(legacy).valid);
const g2 = replayArenaTrace(legacy);
console.log("legacy replay terminal:", JSON.stringify(g2.getTerminalStatus()), "same as recorded:", JSON.stringify(legacy.terminal));
console.log("returns a live game:", g2 instanceof RestaurantGame, typeof g2.checkpointState === "function", typeof g2.state === "function");

const expectThrow = (label: string, mutate: (t: any) => void) => {
  const t = clone(base); mutate(t);
  try { replayArenaTrace(t); console.log("NOT THROWN", label); }
  catch (e) { console.log("threw:", label, "->", String((e as Error).message).slice(0, 70)); }
};
expectThrow("initialState.cash tweak", (t) => { t.initialState.outcomes.cash = 1; });
expectThrow("initialState.reputation tweak", (t) => { t.initialState.reputation = 51; });
expectThrow("checkpoint hash tweak", (t) => { t.replay.inputs[3].stateHash = t.replay.inputs[4].stateHash; });
expectThrow("restaurantStateHash tweak", (t) => { t.replay.inputs[3].restaurantStateHash = t.replay.inputs[4].restaurantStateHash; });
expectThrow("finalStateHash tweak", (t) => { t.replay.finalStateHash = "sha256:" + "0".repeat(64); });
expectThrow("terminal.status tweak", (t) => { t.terminal.status = "abandoned"; });
expectThrow("terminal.tick tweak", (t) => { t.terminal.tick = 23; });
expectThrow("terminal.reason tweak", (t) => { t.terminal.reason = "user_quit"; });
expectThrow("truncated inputs", (t) => { t.replay.inputs = t.replay.inputs.slice(0, 5); });
expectThrow("dropped pass_round-ish input", (t) => { t.replay.inputs.splice(11, 1); });
expectThrow("wrong seed", (t) => { t.seed = 1; });

// runKind required
try { (captureArenaTrace as any)(play(), {}); console.log("NOT THROWN runKind"); } catch (e) { console.log("threw: missing runKind ->", String((e as Error).message).slice(0,80)); }
try { (captureArenaTrace as any)(play(), { runKind: "demo" }); console.log("NOT THROWN bad runKind"); } catch (e) { console.log("threw: bad runKind"); }

// additionalEvents round stamping
const withExtra = play().captureTrace({ runKind: "live", additionalEvents: [
  { tick: 7, kind: "message", timestamp: "2026-09-05T18:00:21.000Z", stateHash: base.events[0]!.stateHash, actorId: "player", text: "note" },
  { tick: 0, kind: "message", timestamp: "2026-09-05T18:00:00.000Z", stateHash: base.events[0]!.stateHash, actorId: "player", text: "opening note", round: 99 },
]});
console.log("extra events:", withExtra.events.filter(e => e.actorId === "player" && e.kind === "message").map(e => [e.tick, e.round]));
console.log("ordered by tick:", withExtra.events.map(e=>e.tick).every((t,i,a)=> i===0 || t>=a[i-1]!));
console.log("count:", withExtra.events.length, "base:", base.events.length);
console.log("extra valid:", JSON.stringify(validateArenaTraceV3(withExtra)).slice(0,300));

// events replacement + sessionId + deletion
const replaced = play().captureTrace({ runKind: "synthetic", sessionId: "game_abc", events: [], deletion: { status: "requested", requestId: "req-1" } });
console.log("replaced:", replaced.events.length, replaced.sessionId, JSON.stringify(replaced.deletion), replaced.runKind);
console.log("replaced valid:", validateArenaTraceV3(replaced).valid);
' 2>&1 | tail -40

