// Replay re-derives the run's own event journal, which is what makes a
// truncated file detectable: the hashes and the terminal record all live in the
// header, so a JSONL export missing event lines still replays. Caller-added
// events are fine; events the run produced and the file no longer carries are
// not.
const recorded = new Set(record.events.map((event) => `${event.tick}|${event.kind}|${event.stateHash}`));
const dropped = game
  .getRecordedEvents()
  .map((event) => `${event.tick}|${event.kind}|${event.stateHash}`)
  .filter((key) => !recorded.has(key));
if (dropped.length > 0) {
  console.error(
    `Event journal is incomplete in ${path}: replay produced ${dropped.length} event(s) the file does not carry (first: ${dropped[0]}). The trace is truncated.`,
  );
  process.exit(1);
}

const terminal = game.getTerminalStatus();
console.log(`${record.replay.inputs.length} inputs, tick ${terminal.tick}, ${terminal.status}`);

